import{_ as e,o,c as a,a3 as d}from"./chunks/framework.DNWyyI0w.js";const u=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"reference/settings.md","filePath":"reference/settings.md"}'),r={name:"reference/settings.md"};function n(s,t,i,c,l,h){return o(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Settings live in <strong>Settings</strong> (per-operator and org-level) and <strong>System Settings</strong> (install-wide). They are stored in Mongo and read through <code>getSystemSettings()</code>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td>Display name / identity</td><td>Who the memory is &quot;about&quot;; used in prompts and attribution</td></tr><tr><td>Default effort mode</td><td>The bottom of the effort resolution chain</td></tr><tr><td>Notifications</td><td>Which lifecycle transitions surface, and where</td></tr></tbody></table><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><p>Provider <strong>profiles</strong> decouple &quot;which endpoint and credentials&quot; from &quot;which model&quot;.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td>Profile id</td><td>Referenced by <code>Run.providerProfile</code>, <code>CustomAgent.profile</code>, and <code>RunAgentConfig.profile</code></td></tr><tr><td>Endpoint &amp; credentials</td><td>Anthropic, or a custom endpoint</td></tr><tr><td>Token prices</td><td>Required for custom endpoints — without them, calls are recorded <code>unpriced</code></td></tr></tbody></table><p>Resolution, most-specific first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run.agentConfigs[actor].profile</span></span>
<span class="line"><span>  → Run.providerProfile</span></span>
<span class="line"><span>    → CustomAgent.profile</span></span>
<span class="line"><span>      → global default</span></span></code></pre></div><p><code>&#39;&#39;</code> or absent means <strong>inherit</strong>, not &quot;override with empty&quot;.</p><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td>Default execution mode</td><td><code>guided</code> or <code>autonomous</code> for new runs</td></tr><tr><td>Global attempt budget</td><td>Ceiling on task retries; a task&#39;s own <code>attemptBudget</code> may lower it but never exceed it</td></tr><tr><td>Optimization mode</td><td><code>off</code> | <code>shadow</code> | <code>canary</code> | <code>on</code> — rollout state for optimizations whose quality must be measured before they may change a verdict or skip real work</td></tr><tr><td>Verification behaviour</td><td>Whether a task may be marked done without a passed gate</td></tr></tbody></table><h2 id="costs" tabindex="-1">Costs <a class="header-anchor" href="#costs" aria-label="Permalink to &quot;Costs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td>Allowances / caps</td><td>Feed <code>usageBlockReason</code>; an exhausted allowance blocks dispatch</td></tr><tr><td>Effort clamping</td><td>Lets <code>clampEffort</code> degrade a run instead of killing it</td></tr><tr><td>Custom token pricing</td><td>Per-model rates for endpoints that do not report cost</td></tr></tbody></table><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p>Install-wide defaults, including the two that decide whether an agent may write unattended:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th><th>Safe value</th></tr></thead><tbody><tr><td><code>defaultBranchMode</code></td><td>Fallback for a project that declares no <code>branch</code></td><td><code>new</code></td></tr><tr><td><code>defaultApproval</code></td><td>Fallback for a project that declares no <code>approval</code></td><td><code>confirm</code></td></tr><tr><td>Auto-approve actions</td><td>Per-action grants (<code>AutoApproveAction</code>) so you can skip specific low-risk prompts without switching a whole project to <code>auto</code></td><td>Grant narrowly</td></tr><tr><td>Scan roots</td><td>Where <code>discover_projects</code> looks for repos</td><td>—</td></tr><tr><td>Sandbox</td><td>Whether delegations run in a Docker sandbox, and the worker pool size</td><td>—</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">These two are the load-bearing ones</p><p><code>defaultBranchMode</code> and <code>defaultApproval</code> are the fallback for every project that does not declare its own policy. Raising them is the single change most likely to let an agent write somewhere you did not intend.</p></div><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>Secrets are stored encrypted and referenced by name from agent MCP configs — not pasted into <code>.mcp.json</code> or committed to a repo. The <code>.env</code> at the repo root holds only what the process itself needs at boot (<code>ANTHROPIC_API_KEY</code>, <code>MONGODB_URI</code>, <code>PORT</code>).</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p>Per-channel configuration (Telegram token, linked identities, session behaviour). See <a href="/docs/guides/telegram">Connecting Telegram</a>.</p><p>See also: <a href="/docs/guides/guardrails">Guardrails</a> · <a href="./project-policy">Project Policy</a></p>`,23)])])}const f=e(r,[["render",n]]);export{u as __pageData,f as default};
